VALUES ('CG-MOD-03', 'contabilidade-geral', 'Saldo final de caixa', 'lacuna_numerica', 'lacuna_numerica_formula', '{"formula":"caixa_liquido","promptTemplate":"Caixa inicial de R$ {a}, recebimentos de R$ {b} e pagamentos de R$ {c} no periodo. Qual o saldo final de caixa, em reais?","explanationTemplate":"Saldo final = caixa inicial + recebimentos - pagamentos = {a} + {b} - {c} = {resultado}.","aMin":1000,"aMax":20000,"bMin":500,"bMax":15000,"cMin":500,"cMax":25000,"decimalPlaces":2,"tolerance":0.01}', NULL, NULL, 'rascunho', 'abner', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z');
