INSERT INTO atlas_item_models (id, theme, title, kind, generator_key, params_json, bloom_level, difficulty_nominal, lifecycle_state, curated_by, created_at, updated_at)
VALUES ('CG-MOD-04', 'contabilidade-geral', 'Depreciacao anual pelo metodo linear', 'lacuna_numerica', 'lacuna_numerica_formula', '{"formula":"depreciacao_linear","promptTemplate":"Um bem foi adquirido por R$ {a} e tem vida util estimada de {b} anos. Qual a depreciacao anual pelo metodo linear, em reais?","explanationTemplate":"Depreciacao anual = valor do bem dividido pela vida util = {a} / {b} = {resultado}.","aMin":6000,"aMax":240000,"bMin":2,"bMax":10,"cMin":0,"cMax":0,"decimalPlaces":2,"tolerance":0.01}', NULL, NULL, 'rascunho', 'abner', '2026-10-08T00:00:00.000Z', '2026-10-08T00:00:00.000Z');
